const pubs = ($('Lire publications').first().json.data || []).filter(p => p.yt_id && Date.now() - Date.parse(p.publiee_le) < 30 * 86400e3);
if (!pubs.length) return [{ json: { ids: '', vide: true } }];
const out = [];
for (let i = 0; i < pubs.length; i += 50) out.push({ json: { ids: pubs.slice(i, i + 50).map(p => p.yt_id).join(','), vide: false } });
return out;

const now = Date.now();
const pubs = ($('Lire publications').first().json.data || []).filter(p => Date.now() - Date.parse(p.publiee_le) < 30 * 86400e3);
const stats = {};
for (const page of $('Statistiques YouTube').all()) for (const v of (page.json.items || [])) stats[v.id] = v;
const tab = j => { const h = (j.columnHeaders || []).map(c => c.name); return (j.rows || []).map(r => Object.fromEntries(r.map((v, i) => [h[i], v]))); };
const ana = Object.fromEntries(tab($('Analytics vidéos').first().json).map(r => [r.video, r]));
const rev = tab($('Analytics revenus').first().json)[0] || {};
const srcs = Object.fromEntries(($('Lire sources').first().json.data || []).map(s => [s.source_nom || s.nom, s]));
const majPubs = [], nouvelles = [], penal = {};
const resume = [];
for (const p of pubs) {
  const ageH = Math.max(1, (now - Date.parse(p.publiee_le)) / 3600e3);
  let statut = p.statut_yt, alerte = p.alerte || '';
  const v = p.yt_id ? stats[p.yt_id] : null;
  const d = { maj: new Date().toISOString() };
  if (p.yt_id && !v && ageH > 2) { statut = 'retiree'; }
  if (v) {
    d.vues_yt = +(v.statistics.viewCount || 0); d.likes_yt = +(v.statistics.likeCount || 0); d.coms_yt = +(v.statistics.commentCount || 0);
    const st = v.status || {};
    statut = st.uploadStatus === 'rejected' ? 'rejetee:' + (st.rejectionReason || '?') : (st.privacyStatus || statut);
    const rr = (v.contentDetails || {}).regionRestriction || {};
    if ((rr.blocked || []).length || (rr.allowed && !rr.allowed.includes('FR'))) statut = 'bloquee:' + (rr.blocked || []).slice(0, 5).join('/');
  }
  d.statut_yt = statut;
  const probleme = /^(retiree|rejetee|bloquee)/.test(statut || '');
  if (probleme && !alerte) {
    d.alerte = `${statut} détecté le ${new Date().toLocaleDateString('fr-FR')}`;
    let sl = []; try { sl = JSON.parse(p.sources || '[]'); } catch (e) {}
    nouvelles.push({ pub: p.pub_id, titre: p.titre, statut, sources: sl });
    for (const s of sl) penal[s] = (penal[s] || 0) + (sl.length === 1 ? 3 : 1); // Short (1 seule source) : exclusion dès le 1er problème ; zapping (plusieurs sources, coupable inconnu) : +1 chacune
  }
  majPubs.push({ filter: { type: 'and', filters: [{ columnName: 'pub_id', condition: 'eq', value: p.pub_id }] }, data: d });
  let segs = []; let hyp = '';
  try { const j = JSON.parse(p.segments || '[]'); segs = Array.isArray(j) ? j : (j.segments || []); hyp = j.hypothese || ''; } catch (e) {}
  resume.push({ type: p.type, titre: p.titre, publiee_il_y_a_h: Math.round(ageH), duree_s: p.duree_s, heure: p.heure, statut,
    vues: d.vues_yt ?? p.vues_yt ?? null, likes: d.likes_yt ?? null, commentaires: d.coms_yt ?? null,
    vues_par_h: d.vues_yt != null ? Math.round(d.vues_yt / ageH * 10) / 10 : null, hypothese: hyp,
    retention_pct: ana[p.yt_id] ? Math.round(ana[p.yt_id].averageViewPercentage) : null, duree_moy_vue_s: ana[p.yt_id] ? ana[p.yt_id].averageViewDuration : null,
    abonnes_gagnes: ana[p.yt_id] ? ana[p.yt_id].subscribersGained : null,
    extraits: segs.map(s => `${s.titre} (${s.source}${s.type_moment ? ' · ' + s.type_moment : ''}${s.theme ? ' · ' + s.theme : ''}${s.personnes ? ' · ' + s.personnes : ''})`).slice(0, 15) });
}
// sources à pénaliser (l'API ne dit pas quelle source a réclamé : chaque source de la vidéo prend +1)
const allSrc = $('Lire sources').first().json.data || [];
const majSrc = [];
for (const [nom, n] of Object.entries(penal)) {
  const s = allSrc.find(x => x.nom === nom); if (!s) continue;
  const score = (s.score_risque || 0) + n;
  const data = { score_risque: score };
  if (score >= 3) data.statut = 'blacklisted';
  majSrc.push({ nom, score, blacklist: !!data.statut, req: { filter: { type: 'and', filters: [{ columnName: 'channel_id', condition: 'eq', value: s.channel_id }] }, data } });
}
// cumul permanent des goûts de Louis : les décisions qui vont être purgées (29-30 j) sont ajoutées aux compteurs de la table sources
const aPurger = ($('Lire vidéos').first().json.data || []).filter(v => ['interessant','pas_interessant','source_ignoree'].includes(v.decision) && now - Date.parse(v.publiee_le) >= 29 * 86400e3 && now - Date.parse(v.publiee_le) < 30 * 86400e3);
const cumul = {};
for (const v of aPurger) { const c = cumul[v.channel_id] ||= { r: 0, x: 0 }; v.decision === 'interessant' ? c.r++ : c.x++; }
for (const [cid, c] of Object.entries(cumul)) {
  const s = allSrc.find(x => x.channel_id === cid); if (!s) continue;
  const ex = majSrc.find(m => m.req.filter.filters[0].value === cid);
  const data = { nb_retenues: (s.nb_retenues || 0) + c.r, nb_rejetees: (s.nb_rejetees || 0) + c.x };
  if (ex) Object.assign(ex.req.data, data); else majSrc.push({ nom: s.nom, score: s.score_risque || 0, blacklist: false, req: { filter: { type: 'and', filters: [{ columnName: 'channel_id', condition: 'eq', value: cid }] }, data } });
}
// cumul permanent par intervenant / camp / thème / type de moment / source
const tagsOf = v => [...String(v.personnes || '').split(',').map(x => x.trim()).filter(Boolean).map(p => ['personne', p]),
  ['camp', v.camp], ['thème', v.theme], ['moment', v.type_moment], ['source', v.source_nom]].filter(([t, x]) => x);
const gExist = Object.fromEntries(($('Lire goûts').first().json.data || []).map(g => [g.cle, g]));
const gInc = {};
for (const v of aPurger) for (const [t, x] of tagsOf(v)) { const k = t + ':' + x; const c = gInc[k] ||= { type: t, valeur: x, r: 0, x: 0 }; v.decision === 'interessant' ? c.r++ : c.x++; }
const gUpd = [], gNew = [];
for (const [k, c] of Object.entries(gInc)) {
  const e = gExist[k];
  if (e) gUpd.push({ filter: { type: 'and', filters: [{ columnName: 'cle', condition: 'eq', value: k }] }, data: { retenues: (e.retenues || 0) + c.r, rejetees: (e.rejetees || 0) + c.x } });
  else gNew.push({ cle: k, type: c.type, valeur: c.valeur, retenues: c.r, rejetees: c.x });
}
const profil = {};
for (const g of Object.values(gExist)) profil[g.cle] = { retenues: g.retenues || 0, rejetees: g.rejetees || 0 };
for (const v of ($('Lire vidéos').first().json.data || []).filter(v => ['interessant','pas_interessant','source_ignoree'].includes(v.decision))) for (const [t, x] of tagsOf(v)) { const p = profil[t + ':' + x] ||= { retenues: 0, rejetees: 0 }; v.decision === 'interessant' ? p.retenues++ : p.rejetees++; }
// goûts de Louis sur 30 jours
const vids = ($('Lire vidéos').first().json.data || []).filter(v => ['interessant','pas_interessant','source_ignoree'].includes(v.decision));
const gouts = {};
for (const s of allSrc) if (s.nb_retenues || s.nb_rejetees) gouts[s.nom] = { retenues: s.nb_retenues || 0, rejetees: s.nb_rejetees || 0 };
for (const v of vids) { const g = gouts[v.source_nom] ||= { retenues: 0, rejetees: 0 }; v.decision === 'interessant' ? g.retenues++ : g.rejetees++; }
const lecons = (($('Lire leçons').first().json.data || [])[0] || {});
const system = `Tu es l'analyste performance de « L'Extrait politique » (zapping politique quotidien + Shorts, YouTube/Facebook/Instagram/TikTok).
Objectif : 3 000 €/mois le plus vite possible, avec deux contraintes absolues : aucun strike, aucune démonétisation.
Chaque jour tu relis les résultats et tu réécris les LEÇONS que l'IA de production appliquera demain (choix des sujets, sources, extraits, ordre, titres, durées).
Méthode :
- base-toi sur les chiffres : rétention (% moyen regardé, durée moyenne vue) en priorité, puis vues/heure, abonnés gagnés, likes, commentaires, et le revenu de la chaîne sur 30 jours en tenant compte de l'âge des vidéos ; une chaîne neuve a peu de données : distingue ce qui est prouvé, probable, ou à tester ;
- intègre les goûts de Louis (ses choix sur Telegram) comme un signal fort mais pas absolu ;
- toute vidéo retirée, rejetée ou bloquée est une alerte droits d'auteur : renforce les règles de prudence sur les sources concernées ;
- garde toujours les règles anti-strike et anti-démonétisation, ne les assouplis jamais ;
- conserve ~20 % d'exploration : propose 1 à 3 hypothèses précises à tester demain ;
- sois concret et court : des règles applicables, pas des généralités.
RÈGLE D'HONNÊTETÉ (impérative) : si "donnees_suffisantes" vaut false, la rubrique 📊 Performances donne seulement les chiffres bruts déjà mesurés, avec l'âge des vidéos, et la phrase « trop tôt pour conclure » — aucun mot comme « confirmé », « faible », « cartonne », « écrase », aucune règle nouvelle tirée de ces chiffres dans les leçons (tu peux seulement noter des pistes à tester). Ensuite : ne présente JAMAIS quelque chose comme « qui marche » ou « qui ne marche pas » sans données de performance mesurées (vues, likes, commentaires) sur au moins 3 publications publiques âgées d'au moins 24 h. Tant que ce n'est pas le cas, écris clairement « Pas encore de données de performance » et ne parle que de ce que Louis a choisi ou écarté (ses goûts), formulé comme tel (« tu as retenu… », « tu as écarté… »), et des hypothèses à tester. Les vidéos encore privées ne comptent pas comme données de performance.
Réponds UNIQUEMENT en JSON : {"lecons":"texte complet des nouvelles leçons (≤ 3500 caractères)","rapport":"message Telegram pour Louis (≤ 900 caractères) en 4 rubriques : 📊 Performances (uniquement des chiffres mesurés, sinon « pas encore de données »), 👤 Tes choix (ce que Louis a retenu/écarté), 🧪 Ce que je teste demain, 💰 Où on en est vers les 3 000 €"}`;
const eligibles = resume.filter(r => r.publiee_il_y_a_h >= 24 && r.statut === 'public').length;
const donnees_suffisantes = eligibles >= 3;
const user = JSON.stringify({ donnees_suffisantes, publications_publiques_de_plus_de_24h: eligibles, chaine_30j: { revenus_estimes_eur: rev.estimatedRevenue ?? 0, vues: rev.views ?? 0, abonnes_gagnes: rev.subscribersGained ?? 0, objectif_mensuel_eur: 3000 }, lecons_actuelles: lecons.texte || '', publications_30j: resume, alertes_nouvelles: nouvelles, sources_penalisees: majSrc.filter(s => s.req.data.score_risque != null).map(s => ({ nom: s.nom, score_risque: s.score, blacklistee: s.blacklist })), gouts_louis_par_etiquette: profil, consigne_gouts: 'Raisonne d’abord par type de moment, thème, intervenant et camp ; la source/chaîne est un signal secondaire.' });
return [{ json: { majPubs, majSrc, nouvelles, gUpd, gNew, version: (lecons.version || 0) + 1, nb_pubs: resume.length,
  body: { model: 'claude-sonnet-4-5', max_tokens: 3000, system, messages: [{ role: 'user', content: user }] } } }];

const a = $('Analyse').first().json;
if (!a.nouvelles.length) return [];
const l = ['🚨 <b>Alerte droits d\'auteur</b>'];
for (const n of a.nouvelles) l.push(`• ${n.titre} → ${n.statut}\n  Sources : ${n.sources.join(', ')}`);
const pen = a.majSrc.filter(s => s.req.data.score_risque != null);
if (pen.length) l.push('', 'Sources pénalisées : ' + pen.map(s => `${s.nom} (${s.score}/3${s.blacklist ? ', exclue' : ''})`).join(', '));
l.push('', 'Les publications continuent sans les sources exclues. Si tu sais quelle chaîne a réclamé (YouTube Studio → Droits d\'auteur), dis-le à Claude pour affiner.');
return [{ json: { texte: l.join('\n') } }];

const a = $('Analyse').first().json;
const txt = ($input.first().json.content || []).map(x => x.text || '').join('');
const r = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
if (!r.lecons || r.lecons.length < 200) throw new Error('Leçons générées trop courtes');
return [{ json: { row: { data: [{ version: a.version, date: new Date().toISOString(), texte: r.lecons.slice(0, 6000), rapport: r.rapport }] },
  texte: (Date.now() > Date.parse('2026-12-20') ? '⏰ <b>Rappel</b> : l\'accès Facebook/Instagram expire vers le 3 janvier 2027. Dis à Claude de le renouveler (Graph API Explorer → nouveau jeton).\n\n' : '') + `📈 <b>Bilan quotidien · leçons v${a.version}</b> (${a.nb_pubs} publications analysées)\n\n${String(r.rapport).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}` } }];
